/**
 * Phase 10.1: Lexer Enhancement Tests
 * Testing design directive token recognition
 */

import { Lexer } from './lexer/lexer';
import { TokenType } from './lexer/token';

console.log('\n╔════════════════════════════════════════════════════════╗');
console.log('║  Phase 10.1: Lexer Enhancement - Design Directives   ║');
console.log('╚════════════════════════════════════════════════════════╝\n');

// Test 1: @animation directive
console.log('✓ Test 1: @animation directive');
const input1 = `component Card {
  @animation fadeIn {
    duration: 300
    opacity: 0 → 1
  }
}`;

const lexer1 = new Lexer(input1);
const tokens1 = lexer1.tokenize();
const animationToken = tokens1.find(t => t.type === TokenType.ANIMATION_DESIGN);
if (animationToken) {
  console.log(`  ✅ Found ANIMATION_DESIGN token: "${animationToken.value}"`);
} else {
  console.log('  ❌ ANIMATION_DESIGN token not found');
}

// Test 2: @glass directive
console.log('\n✓ Test 2: @glass directive');
const input2 = `@glass {
  background: rgba(255, 255, 255, 0.1)
  backdropFilter: blur(10px)
}`;

const lexer2 = new Lexer(input2);
const tokens2 = lexer2.tokenize();
const glassToken = tokens2.find(t => t.type === TokenType.GLASS_DESIGN);
if (glassToken) {
  console.log(`  ✅ Found GLASS_DESIGN token: "${glassToken.value}"`);
} else {
  console.log('  ❌ GLASS_DESIGN token not found');
}

// Test 3: @3d directive
console.log('\n✓ Test 3: @3d directive');
const input3 = `@3d {
  perspective: 1000px
  rotateX: 10deg
}`;

const lexer3 = new Lexer(input3);
const tokens3 = lexer3.tokenize();
const transformToken = tokens3.find(t => t.type === TokenType.TRANSFORM3D_DESIGN);
if (transformToken) {
  console.log(`  ✅ Found TRANSFORM3D_DESIGN token: "${transformToken.value}"`);
} else {
  console.log('  ❌ TRANSFORM3D_DESIGN token not found');
}

// Test 4: @micro directive
console.log('\n✓ Test 4: @micro directive');
const input4 = `@micro {
  selector: .button
  event: hover
  action: pulse
}`;

const lexer4 = new Lexer(input4);
const tokens4 = lexer4.tokenize();
const microToken = tokens4.find(t => t.type === TokenType.MICRO_DESIGN);
if (microToken) {
  console.log(`  ✅ Found MICRO_DESIGN token: "${microToken.value}"`);
} else {
  console.log('  ❌ MICRO_DESIGN token not found');
}

// Test 5: @scroll directive
console.log('\n✓ Test 5: @scroll directive');
const input5 = `@scroll {
  selector: .reveal
  animation: fadeIn
  offset: -100px
}`;

const lexer5 = new Lexer(input5);
const tokens5 = lexer5.tokenize();
const scrollToken = tokens5.find(t => t.type === TokenType.SCROLL_DESIGN);
if (scrollToken) {
  console.log(`  ✅ Found SCROLL_DESIGN token: "${scrollToken.value}"`);
} else {
  console.log('  ❌ SCROLL_DESIGN token not found');
}

// Test 6: Generic @ symbol (not followed by design directive keyword)
console.log('\n✓ Test 6: Generic @ symbol (not design directive)');
const input6 = `@deprecated
@resolver`;

const lexer6 = new Lexer(input6);
const tokens6 = lexer6.tokenize();
const atTokens = tokens6.filter(t => t.type === TokenType.AT);
const identTokens = tokens6.filter(t => t.type === TokenType.IDENT);

if (atTokens.length > 0) {
  console.log(`  ✅ Found AT token(s): ${atTokens.map(t => t.value).join(', ')}`);
}
if (identTokens.length > 0) {
  console.log(`  ✅ Found IDENT token(s): ${identTokens.map(t => t.value).join(', ')}`);
}

// Test 7: All design directives in one component
console.log('\n✓ Test 7: All design directives in one component');
const input7 = `component HeroCard {
