          this.advance(); // '(' 소비
          while (!this.check(TokenType.RPAREN) && !this.check(TokenType.EOF)) {
            if (this.check(TokenType.STRING)) {
              const raw = String(this.advance().value);
              // 따옴표 제거 ("https://dclub.kr" → https://dclub.kr)
              domains.push(raw.replace(/^["']|["']$/g, ''));
