            // git_hook 어노테이션은 이벤트 타입을 추출하여 "git_hook:pre_commit" 형태로 저장
            if (this.check(TokenType.LPAREN)) {
              this.advance();
              if (annotName === 'git_hook') {
                // event: .pre_commit 또는 event: .pre_push 추출
