                let depth = 1;
                while (depth > 0 && !this.check(TokenType.EOF)) {
                  if (this.check(TokenType.LPAREN)) { depth++; this.advance(); continue; }
                  if (this.check(TokenType.RPAREN)) { depth--; if (depth === 0) break; this.advance(); continue; }
