                // → "log_policy:max_size=104857600,backups=5,compress=gzip,target=/var/log/app.log"
                let lpMaxSize  = '104857600'; // 100MB 기본
                let lpBackups  = '3';
                let lpCompress = 'none';
                let lpTarget   = '';
                let depth = 1;
                while (depth > 0 && !this.check(TokenType.EOF)) {
